-- IRS Statistics of Income by ZIP code -- returns filed, income brackets, and totals per ZIP (180K rows).
-- Auto-generated by scripts/gen_evidence_pages.py: 179,796 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
-- grouped on year-like text/number column TAX_YEAR (NOT date-cast -- avoids the 8-digit epoch trap); LIMIT bounds it.
select "TAX_YEAR" as year, count(*) as records
from THE_LIBRARY.MONEY.IRS_INCOME_STATS_BY_ZIP
group by 1
order by 1
limit 1000
